)
@click.argument("table")
@click.option(
    "--type",
    type=(
        str,
        click.Choice(list(VALID_COLUMN_TYPES), case_sensitive=False),
    ),
    multiple=True,
    help="Change column type to INTEGER, TEXT, FLOAT, REAL, BLOB or ANY",
)
@click.option("--drop", type=str, multiple=True, help="Drop this column")
@click.option(
    "--rename", type=(str, str), multiple=True, help="Rename this column to X"
)
@click.option("-o", "--column-order", type=str, multiple=True, help="Reorder columns")
@click.option("--not-null", type=str, multiple=True, help="Set this column to NOT NULL")
@click.option(
    "--not-null-false", type=str, multiple=True, help="Remove NOT NULL from this column"
)
@click.option("--pk", type=str, multiple=True, help="Make this column the primary key")
@click.option(
    "--pk-none", is_flag=True, help="Remove primary key (convert to rowid table)"
)
@click.option(
    "--default",
    type=(str, str),
    multiple=True,
    help="Set default value for this column",
)
@click.option(
    "--default-none", type=str, multiple=True, help="Remove default from this column"
)
@click.option(
    "add_foreign_keys",
    "--add-foreign-key",
    type=(str, str, str),
    multiple=True,
    help="Add a foreign key constraint from a column to another table with another column",
)
@click.option(
    "drop_foreign_keys",
    "--drop-foreign-key",
    type=str,
    multiple=True,
    help="Drop foreign key constraint for this column",
)
@click.option(
    "--strict/--no-strict",
    default=None,
    help="Enable or disable STRICT mode (default: preserve current mode)",
)
@click.option("--sql", is_flag=True, help="Output SQL without executing it")
@load_extension_option
def transform(
    path,
    table,
    type,
    drop,
    rename,
    column_order,
    not_null,
    not_null_false,
    pk,
    pk_none,
    default,
    default_none,
    add_foreign_keys,
    drop_foreign_keys,
    strict,
    sql,
    load_extension,
):
    """Transform a table beyond the capabilities of ALTER TABLE

    Example:

    \b
        sqlite-utils transform mydb.db mytable \\
            --drop column1 \\
            --rename column2 column_renamed
    """
    db = sqlite_utils.Database(path)
    _register_db_for_cleanup(db)
    _load_extensions(db, load_extension)
    types = {}
    for column, ctype in type:
        if ctype.upper() not in VALID_COLUMN_TYPES:
            raise click.ClickException(
                f"column types must be one of {VALID_COLUMN_TYPES}"
            )
        types[column] = ctype.upper()

    not_null_dict = {}
    for column in not_null:
        not_null_dict[column] = True
    for column in not_null_false:
        not_null_dict[column] = False

    default_dict = {}
    for column, value in default:
        default_dict[column] = value
    for column in default_none:
        default_dict[column] = None

    drop_set = set(drop)
    rename_dict = dict(rename)
    column_order_list = list(column_order) or None
    drop_foreign_keys_value = drop_foreign_keys or None
    add_foreign_keys_value = add_foreign_keys or None
    pk_value = DEFAULT
    if pk:
        if len(pk) == 1:
            pk_value = pk[0]
        else:
            pk_value = pk
    elif pk_none:
        pk_value = None

    table_obj = db.table(table)
    if sql:
        for line in table_obj.transform_sql(
            types=types,
            drop=drop_set,
            rename=rename_dict,
            column_order=column_order_list,
            not_null=not_null_dict,
            pk=pk_value,
            defaults=default_dict,
            drop_foreign_keys=drop_foreign_keys_value,
            add_foreign_keys=add_foreign_keys_value,
            strict=strict,
        ):
            click.echo(line)
    else:
        table_obj.transform(
            types=types,
            drop=drop_set,
            rename=rename_dict,
            column_order=column_order_list,
            not_null=not_null_dict,
            pk=pk_value,
            defaults=default_dict,
            drop_foreign_keys=drop_foreign_keys_value,
            add_foreign_keys=add_foreign_keys_value,
            strict=strict,
        )


