def output_rows(iterator, headers, nl, arrays, json_cols, ascii_=False):
    # Duplicate column names would collide as dictionary keys, so rename
    # later occurrences id, id -> id, id_2 - CSV and table output keep
    # the original duplicate headers since they never build dictionaries
    headers = dedupe_keys(headers)
    # We have to iterate two-at-a-time so we can know if we
    # should output a trailing comma or if we have reached
    # the last row.
    current_iter, next_iter = itertools.tee(iterator, 2)
    next(next_iter, None)
    first = True
    for row, next_row in itertools.zip_longest(current_iter, next_iter):
        is_last = next_row is None
        data = row
        if json_cols:
            # Any value that is a valid JSON string should be treated as JSON
            data = [maybe_json(value) for value in data]
        if not arrays:
            data = dict(zip(headers, data))
        line = "{firstchar}{serialized}{maybecomma}{lastchar}".format(
            firstchar=("[" if first else " ") if not nl else "",
            serialized=json.dumps(data, default=json_binary, ensure_ascii=ascii_),
            maybecomma="," if (not nl and not is_last) else "",
            lastchar="]" if (is_last and not nl) else "",
        )
        yield line
        first = False
    if first:
        # We didn't output any rows, so yield the empty list
        yield "[]"


def maybe_json(value):
    if not isinstance(value, str):
        return value
    stripped = value.strip()
    if not (stripped.startswith(("{", "["))):
        return value
    try:
        return json.loads(stripped)
    except ValueError:
        return value


def json_binary(value):
    if isinstance(value, bytes):
        return {"$base64": True, "encoded": base64.b64encode(value).decode("latin-1")}
    else:
        raise TypeError


def verify_is_dict(doc):
    if not isinstance(doc, dict):
        raise click.ClickException(
            f"Rows must all be dictionaries, got: {repr(doc)[:1000]}"
        )
    return doc


def _load_extensions(db, load_extension):
    if load_extension:
        db.conn.enable_load_extension(True)
        for ext in load_extension:
            if ext == "spatialite" and not os.path.exists(ext):
                found = find_spatialite()
                if found is None:
                    raise click.ClickException("Could not find SpatiaLite extension")
                ext = found
            if ":" in ext:
                path, _, entrypoint = ext.partition(":")
                db.conn.execute("SELECT load_extension(?, ?)", [path, entrypoint])
            else:
                db.conn.load_extension(ext)


def _register_functions(db, functions):
    # Register any Python functions as SQL functions:
    # Check if this is a file path
    if "\n" not in functions and functions.endswith(".py"):
        try:
            functions = pathlib.Path(functions).read_text()
        except FileNotFoundError:
            raise click.ClickException(f"File not found: {functions}")

    sqlite3.enable_callback_tracebacks(True)
    globals = {}
    try:
        exec(functions, globals)  # noqa: S102
    except SyntaxError as ex:
        raise click.ClickException(f"Error in functions definition: {ex}")
    # Register all callables in the locals dict:
    for name, value in globals.items():
        if callable(value) and not name.startswith("_"):
            db.register_function(value, name=name)


def _maybe_register_functions(db, functions_list):
    if not functions_list:
        return
    for functions in functions_list:
        if isinstance(functions, str) and functions.strip():
            _register_functions(db, functions)


def _rows_from_code(code):
    # code may be a path to a .py file
    if "\n" not in code and code.endswith(".py"):
        try:
            code = pathlib.Path(code).read_text()
        except FileNotFoundError:
            raise click.ClickException(f"File not found: {code}")
    namespace: dict[str, Any] = {}
    try:
        exec(code, namespace)  # noqa: S102
    except SyntaxError as ex:
        raise click.ClickException(f"Error in --code: {ex}")
    rows: Any = namespace.get("rows")
    if callable(rows):
        rows = rows()
    if isinstance(rows, dict):
        rows = [rows]
    error = click.ClickException(
        "--code must define a 'rows' function or iterable of rows to insert"
    )
    if rows is None or isinstance(rows, (str, bytes)):
        raise error
    try:
        iter(rows)
    except TypeError:
        raise error
    return rows

