    """Return column-level and table-level UNIQUE constraints."""
    body_info = _table_body(create_sql)
    if body_info is None:
        return []
    body, body_start = body_info
    uniques: list[Unique] = []
    for item, item_start, _ in _split_spans(body, _lex(body)):
