    assert fresh_db['Go"sh'].xindexes == [
        XIndex(
            name='idx_Go"sh_c"1',
            columns=[
                XIndexColumn(seqno=0, cid=1, name='c"1', desc=0, coll="BINARY", key=1),
                XIndexColumn(seqno=1, cid=-1, name=None, desc=0, coll="BINARY", key=0),
            ],
        )
    ]


